Action.Str:
dir=%dir
p=%par11 b=%btext t=$(date +%s)
j=$(grep ",${p}," ${dir}/预览剪贴板.csv |awk -F, -v b="$b" -v t="$t" '{print $1","t","$3","$4","$5","b}')
if [ "$(grep ",${p}," ${dir}/预览剪贴板.csv)" ]; then sed -i -r "s|^[^
]+,${p},[^
]+\$|${j}|" ${dir}/预览剪贴板.csv sed -i -r "s|^[^
]+,${p},[^
]+\$|${j}|" ${dir}/缓存.csv fi

dir=%dir
text=$(echo "%btext" |base64 -d)

if m=$(sed -rn '
/^[0-9a-f]{32}$/ {
    x
    /:notfound/ {
        s/:.*//
        p
    }
    g
    s/^//
    s/$//
    s/$/:notfound/
    h
    d
}
/'${text}'/ {
    x
    s/:notfound$/:found/
    x
}
$ {
    x
    /:notfound/ {
        s/:.*//
        p
    }
}
' "${dir}/剪贴板.txt") ; then
echo "${m}" |tac |paste -s -d ,
fi

{
  "actions": [{
    "@type": "type.googleapis.com/ForEach",
    "data": "argOf$par",
    "delimiter": [","],
    "actions": [{
      "@type": "type.googleapis.com/ShellCommand",
      "command": "files\u003d\u0027argOf$file\u0027\n[ \u0027{foreachData}\u0027 ] \u0026\u0026 num\u003d\u0027.{foreachData}\u0027\nmd5n\u003d${files##*/}\nmd5\u003d${md5n%.*}\nfilen\u003d${files%.*}$num\nfile\u003d${filen%.0*}\n\nif [ -f $file ]; then\ncat $file\nelse\nsed -rn \u0027/^\b\u0002\u0002\u0002\b\u0027${md5}\u0027$/{\n  :loop\n  n\n  /^\b\u0002\u0002\u0002\b[0-9a-f]{32}$/!{\n    p\n    b loop\n  }\n  q\n}\u0027 /sdcard/Tasker/剪贴板/剪贴板.txt\nfi",
      "customContextDataKey": {
