###------###
{"type":"da"}

dir=%dir
p2=%par2 m=%md5 b=%bclip t=$(date +%s) ind=%index
j=$(grep ",${p2}" ${dir}/预览剪贴板.csv |awk -F, -v m="$m" -v b="$b" -v t="$t" -v ind="$ind" '{if(index(ind, "index") == 0) {print t","t","$3","$4","m"."ind","b} else {print t","t","$3","$4","m","b}}')
if [ "$(grep ",${p2}" ${dir}/预览剪贴板.csv)" ]; then sed -i -r "s|^[^
]+,${p2}[^
]+\$|${j}|" ${dir}/预览剪贴板.csv sed -i -r "s|^[^
]+,${p2}[^
]+\$|${j}|" ${dir}/缓存.csv [ "$p2" != "$m" ] && rm -f ${dir}/*/${p2}* fi

// 获取变量
tdir = local('tdir');
fileName = local('md5');
baseDir = local('dir') + '/' + tdir + '/';

if (!fileName) exit();

text = readFile(baseDir + fileName);
totalPath = baseDir + fileName;

// 计算总字节数，判断是否需要拆分
encoder = new TextEncoder();
totalBytes = encoder.encode(text).length;
MAX_SIZE = 100 * 1024; // 100 KB

if (totalBytes <= MAX_SIZE) {
    // 未超标，只保留总文件
    exit();
}

// ==== 拆分逻辑：保证首尾无空白，且不截断多字节字符 ====
// 分离文件名
lastDot = fileName.lastIndexOf('.');
if (lastDot > 0) {
    baseName = fileName.substring(0, lastDot);
    ext = fileName.substring(lastDot + 1);
} else {
    baseName = fileName;
    ext = '';
}

let splitPoints = [0];         // 切割点（字符索引）
let start = 0;                 // 当前分片的起始字符索引
let currentBytes = 0;          // 当前分片已累积的字节数
let lastValidSplit = -1;       // 最近一个合法切割点（两侧都非空白）
let prevIsSpace = null;        // 上一个字符是否为空白

let len = text.length;
let i = 0;                     // 当前字符的码点索引（代理对会跳2）

while (i < len) {
    let code = text.codePointAt(i);
    let ch = String.fromCodePoint(code);

    // UTF-8 字节数（无需调用 encoder）
    let charBytes = code < 0x80 ? 1 :
                    code < 0x800 ? 2 :
                    code < 0x10000 ? 3 : 4;

    // 空白判断
    let isSpace = (ch === ' ' || ch === '\t' || ch === '\n' ||
                   ch === '\r' || ch === '\f' || ch === '\v' ||
                   ch === '\u00A0' || ch === '\u1680' ||
                   (ch >= '\u2000' && ch <= '\u200A') ||
                   ch === '\u2028' || ch === '\u2029' ||
                   ch === '\u202F' || ch === '\u205F' ||
                   ch === '\u3000' || ch === '\uFEFF');

    // 更新“合法切割点”：当前字符非空白，且上一个字符也非空白，
    // 且不在分片开头，此时 i 可作为下一片的起点
    if (!isSpace && prevIsSpace !== null && !prevIsSpace && i > start) {
        lastValidSplit = i;
    }

    // 检查是否超出 MAX_SIZE
    if (currentBytes + charBytes > MAX_SIZE && i > start) {
        let splitIdx;
        if (lastValidSplit > start) {
            // 优先使用合法切割点，保证首尾无空白
            splitIdx = lastValidSplit;
        } else {
            // 极端情况：整个分片内找不到合法切割点，强制在当前字符前切
            splitIdx = i;
        }

        splitPoints.push(splitIdx);

        // 重置状态，从切割点开始新分片
        start = splitIdx;
        currentBytes = 0;
        lastValidSplit = -1;
        prevIsSpace = null;
        i = splitIdx;   // 回退，下一次循环将从切割点字符重新处理
        continue;
    }

    currentBytes += charBytes;
    prevIsSpace = isSpace;

    // 前进到下一个字符
    i += (code > 0xFFFF) ? 2 : 1;
}

// 将末尾加入切割点
if (start < len) {
    splitPoints.push(len);
}

// 按切割点生成并写出文件
let index = 0;
for (let k = 0; k < splitPoints.length - 1; k++) {
    let segStart = splitPoints[k];
    let segEnd = splitPoints[k + 1];
    let chunkStr = text.substring(segStart, segEnd);

    let outFileName;
    if (ext) {
        outFileName = baseDir + baseName + '.' + (index + 1) + '.' + ext;
    } else {
        outFileName = baseDir + baseName + '.' + (index + 1);
    }
    writeFile(outFileName, chunkStr, false);
    index++;
}

setLocal("%index", index);
